{"content":"import json
import pandas as pd

# --- Load source_a ---
with open('/data/source_a/users.json') as f:
    data_a = json.load(f)
df_a = pd.DataFrame(data_a)
# map: id->user_id, full_name->name, email->email, registration_date->created_date, status->status
df_a = df_a.rename(columns={
    'id': 'user_id',
    'full_name': 'name',
    'email': 'email',
    'registration_date': 'created_date',
    'status': 'status'
})

# --- Load source_b ---
df_b = pd.read_csv('/data/source_b/users.csv')
# map: user_id stays, name stays, email_address->email, created_at->created_date, is_active->status
df_b = df_b.rename(columns={
    'email_address': 'email',
    'created_at': 'created_date',
    'is_active': 'status'
})

# --- Load source_c ---
df_c = pd.read_parquet('/data/source_c/users.parquet')
# map: userId->user_id, userName->name, email stays, joined->created_date, active->status
df_c = df_c.rename(columns={
    'userId': 'user_id',
    'userName': 'name',
    'joined': 'created_date',
    'active': 'status'
})


def normalize_status(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, bool):
        return 'active' if v else 'inactive'
    if isinstance(v, (int, float)):
        # 1/0 convention; also handle numpy ints
        try:
            if int(v) == 1:
                return 'active'
            if int(v) == 0:
                return 'inactive'
        except Exception:
            pass
        return str(v)
    if isinstance(v, str):
        s = v.strip()
        low = s.lower()
        if low in ('true', '1', 'active', 'yes', 'y', 't'):
            return 'active'
        if low in ('false', '0', 'inactive', 'no', 'n', 'f'):
            return 'inactive'
        return s
    return str(v)


def normalize_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    # Handle pandas Timestamp / datetime
    if isinstance(v, (pd.Timestamp,)):
        return v.strftime('%Y-%m-%d')
    try:
        import datetime as _dt
        if isinstance(v, (_dt.datetime, _dt.date)):
            return v.strftime('%Y-%m-%d')
    except Exception:
        pass
    s = str(v).strip()
    # Try parsing common datetime forms, output YYYY-MM-DD
    try:
        ts = pd.to_datetime(s)
        return ts.strftime('%Y-%m-%d')
    except Exception:
        return s


def normalize_str(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except Exception:
        pass
    return str(v).strip()

# Normalize columns
for df in (df_a, df_b, df_c):
    df['user_id'] = df['user_id'].astype(int)
    df['name'] = df['name'].apply(normalize_str)
    df['email'] = df['email'].apply(normalize_str)
    df['created_date'] = df['created_date'].apply(normalize_date)
    if 'status' in df.columns:
        df['status'] = df['status'].apply(normalize_status)
    else:
        df['status'] = None

# Keep only unified columns
cols = ['user_id', 'name', 'email', 'created_date', 'status']
df_a = df_a[cols]
df_b = df_b[cols]
df_c = df_c[cols]

# Index by user_id
a_map = {int(r['user_id']): r for r in df_a.to_dict(orient='records')}
b_map = {int(r['user_id']): r for r in df_b.to_dict(orient='records')}
c_map = {int(r['user_id']): r for r in df_c.to_dict(orient='records')}

all_ids = sorted(set(a_map) | set(b_map) | set(c_map))

fields = ['name', 'email', 'created_date', 'status']
conflicts = []
merged_rows = []

for uid in all_ids:
    ra = a_map.get(uid)
    rb = b_map.get(uid)
    rc = c_map.get(uid)
    merged = {'user_id': int(uid)}
    for field in fields:
        va = ra[field] if ra is not None else None
        vb = rb[field] if rb is not None else None
        vc = rc[field] if rc is not None else None
        # priority: a > b > c
        if va is not None:
            selected = va
        elif vb is not None:
            selected = vb
        elif vc is not None:
            selected = vc
        else:
            selected = None
        merged[field] = selected
        # conflict detection: among non-None present values, if >1 distinct -> conflict
        present = {}
        if ra is not None and va is not None:
            present['source_a'] = va
        if rb is not None and vb is not None:
            present['source_b'] = vb
        if rc is not None and vc is not None:
            present['source_c'] = vc
        if len(present) >= 2 and len(set(present.values())) > 1:
            values = {}
            if ra is not None:
                values['source_a'] = va
            if rb is not None:
                values['source_b'] = vb
            if rc is not None:
                values['source_c'] = vc
            conflicts.append({
                'user_id': int(uid),
                'field': field,
                'values': values,
                'selected': selected
            })
    merged_rows.append(merged)

merged_df = pd.DataFrame(merged_rows, columns=['user_id', 'name', 'email', 'created_date', 'status'])
merged_df = merged_df.sort_values('user_id').reset_index(drop=True)
# Enforce types
merged_df['user_id'] = merged_df['user_id'].astype('int64')
for c in ['name', 'email', 'created_date', 'status']:
    merged_df[c] = merged_df[c].astype('string')

merged_df.to_parquet('/app/merged_users.parquet', index=False)

report = {
    'total_conflicts': len(conflicts),
    'conflicts': sorted(conflicts, key=lambda x: (x['user_id'], x['field']))
}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print(merged_df.to_string())
print(merged_df.dtypes)
print(json.dumps(report, indent=2))
